// Function to scale menu on window resize
function scale(x) {
    const menuToggle = document.getElementById('menu-toggle');
    const anyLightboxOpen = document.querySelector("[id^='Lightbox_'][style*='display: flex']");

    if (x.matches && !anyLightboxOpen) { // Only show menu-toggle if no lightbox is open
        menuToggle.style.display = 'flex';
    } else {
        menuToggle.style.display = 'none';
    }
}

var x = window.matchMedia("(max-width: 1000px)");
scale(x); // Call listener function at runtime
x.addListener(scale); // Attach listener function on state changes 

document.addEventListener('DOMContentLoaded', function() {
    console.log('DOM fully loaded and parsed');

    // Initialize the lightboxes when DOM is ready
    initializeLightboxes();

    // Preload the first media item for the first lightbox
    preloadFirstMedia();
});

// Function to initialize the lightboxes
function initializeLightboxes() {
    console.log('Initializing lightboxes');

    // Select all elements with the class 'modal' (lightbox class)
    const lightboxes = document.querySelectorAll('.modal');
    console.log('Found lightboxes:', lightboxes);

    // If no lightboxes are found, log an error and stop the function
    if (lightboxes.length === 0) {
        console.error('No lightboxes found. Check your HTML.');
        return;
    }

    // Generate an array of folder IDs for batch fetching
    const folderIds = Array.from(lightboxes).map((lightbox, index) => `folder_${index + 1}`);
    fetchMediaBatch(folderIds); // Fetch media for all lightboxes in one batch
}

// Function to preload the first media item (e.g., the first image/video in the first lightbox)
function preloadFirstMedia() {
    console.log('Preloading the first media item');

    const firstLightbox = document.querySelector('.modal');
    if (firstLightbox) {
        const firstMedia = firstLightbox.querySelector('img');
        if (firstMedia) {
            console.log('Preloading first media item:', firstMedia.src);
            const img = new Image(); // Create a new image element to preload
            img.src = firstMedia.src; // Set the source to preload the image
        }
    }
}

function fetchMediaBatch(folderIds) {
    console.log(`Fetching first media (image) for folders: ${folderIds.join(', ')}`);

    // Adjust folder IDs to use 'lightbox_' prefix instead of 'folder_'
    const lightboxFolderIds = folderIds.map(folderId => {
        // Replace "folder_" with "lightbox_" only if needed
        return folderId.replace(/^folder_/, 'lightbox_');
    });

    // Log the folder IDs after replacement to verify
    console.log('Adjusted folder IDs:', lightboxFolderIds);

    // Make a single fetch request to get the first media (image) for all the lightboxes
    fetch(`https://new-vhym.onrender.com/api/get-cloudinary-media?folders=${lightboxFolderIds.join(',')}`)
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            return response.json();
        })
        .then(data => {
            // Assuming the server returns media for each folder in the response as an object
            lightboxFolderIds.forEach((folderId, index) => {
                const mediaItems = data[folderId] || []; // Get the media items for the folder
                const lightbox = document.getElementById(`Lightbox_${index + 1}`);
                if (lightbox) {
                    // Find the first image (if any) for the folder
                    const firstImage = mediaItems.find(media => media.type === 'image');
                    if (firstImage) {
                        const mediaElement = document.createElement('img');
                        mediaElement.src = firstImage.src;
                        mediaElement.alt = `First image for ${folderId}`;
                        mediaElement.classList.add("image-slide");

                        // Add the first image to the lightbox
                        const slide = document.createElement('div');
                        slide.classList.add('slide', `slide${index + 1}`);
                        slide.appendChild(mediaElement);
                        lightbox.querySelector('.modal-content').appendChild(slide);

                        console.log(`Added first image to lightbox ${index + 1}: ${firstImage.src}`);
                    } else {
                        console.log(`No image found for folder ${folderId}`);
                    }
                } else {
                    console.error(`Lightbox with ID "Lightbox_${index + 1}" not found.`);
                }
            });
        })
        .catch(error => {
            console.error('Error fetching media:', error);
        });
}


let slideIndex = 1; // Initialize globally
let mediaLoaded = {}; // Object to track if media has been loaded for each lightbox

let lastScrollPosition = 0;

// Function to load media for a specific lightbox
function loadMedia(lightboxId) {
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const mediaContainer = lightbox.querySelector(".modal-content");

    if (!mediaContainer) return;

    // If media is already loaded (from preload or cache), skip the fetch
    if (mediaLoaded[lightboxId]) {
        console.log(`Media for Lightbox ${lightboxId} already loaded. Skipping fetch.`);
        return;
    }

    // Ensure exact lightboxId is used to construct the folder name
    const folderName = `lightbox_${lightboxId}`;
    console.log(`Fetching media for folder: ${folderName}`);
    const isMobile = window.matchMedia("(max-width: 1000px)").matches;

    fetchMediaData(folderName, lightboxId, isMobile); // Call new fetch function for better handling
}

function fetchMediaData(folderName, lightboxId, isMobile, retries = 3) {
    fetch(`https://new-vhym.onrender.com/api/get-cloudinary-media?folder=${folderName}`)
        .then(response => response.json())
        .then(mediaFiles => {
            const firstMediaKey = `firstMedia_${folderName}`;
            const preloadedFirstMedia = sessionStorage.getItem(firstMediaKey);

            // Remove first media if it's already preloaded
            if (preloadedFirstMedia) {
                const preloadedMedia = JSON.parse(preloadedFirstMedia);
                if (mediaFiles.length > 0 && mediaFiles[0].src === preloadedMedia[0].src) {
                    mediaFiles.shift(); // Remove first media
                }
            }

            console.log("Fetched remaining media files:", mediaFiles);
            displayMediaFiles(mediaFiles, lightboxId, isMobile);
            mediaLoaded[lightboxId] = true;
        })
        .catch(err => {
            console.error("Error loading media:", err);
            if (retries > 0) {
                console.log(`Retrying... Remaining retries: ${retries}`);
                setTimeout(() => fetchMediaData(folderName, lightboxId, isMobile, retries - 1), 2000);
            } else {
                alert(`Error loading media for Lightbox ${lightboxId}: ${err.message}`);
            }
        });
}


// Function to display media files in the lightbox
function displayMediaFiles(mediaFiles, lightboxId, isMobile) {
    const mediaContainer = document.getElementById(`Lightbox_${lightboxId}`).querySelector(".modal-content");

    // Ensure existing content is not removed
    mediaFiles.forEach((media, index) => {
        let div = document.createElement("div");
        div.classList.add("slide", `slide${lightboxId}`);

        if (media.type === "video") {
            let video = document.createElement("video");
            video.className = "videoslide";
            video.src = media.src;
            video.controls = true;
            video.preload = index < 3 ? "auto" : "none"; // Only preload first few videos
            div.appendChild(video);
        } else {
            let img = document.createElement("img");

            // Use the transformed URL returned from the server (no further transformations needed)
            img.src = media.src;
            img.className = "image-slide";
            img.loading = index < 3 ? "eager" : "lazy"; // Lazy loading for images after the first few
            img.alt = media.alt || `Lightbox Image ${index + 1}`;

            div.appendChild(img);
        }

        mediaContainer.appendChild(div);
    });

    showSlide(lightboxId, 1);
}

// Function to open the lightbox
function openLightbox(lightboxId) {
    lastScrollPosition = window.scrollY || window.pageYOffset;
    loadMedia(lightboxId); // Only fetch media for the exact lightbox

    document.querySelectorAll("[id^='Lightbox_']").forEach(lightbox => {
        if (lightbox.id !== `Lightbox_${lightboxId}`) {
            lightbox.style.display = "none";
        }
    });

    document.getElementById(`Lightbox_${lightboxId}`).style.display = "flex";
    document.getElementById(`projecttitle_${lightboxId}`).style.display = "block";
    document.getElementById("mouseTarget").style.display = "none";
    document.body.style.overflow = "hidden";
    document.getElementById("rowid").style.display = "none";
    document.getElementById("menu-toggle").style.display = "none";
    document.querySelector("footer").style.display = "none";
    document.getElementById("social_elements2").style.display = "none";

    setKeys(lightboxId);
    scale(x);

    let lastSlide = localStorage.getItem(`lastSlide_${lightboxId}`);
    if (lastSlide) {
        toSlide(lightboxId, parseInt(lastSlide));
    } else {
        toSlide(lightboxId, 1);
    }
}

// Function to store the last viewed slide
function storeLastSlide(lightboxId, slideIndex) {
    localStorage.setItem(`lastSlide_${lightboxId}`, slideIndex);
}

// Function to change slides
function toSlide(lightboxId, slideIndex) {
    showSlide(lightboxId, slideIndex);
    storeLastSlide(lightboxId, slideIndex);
}

// Function to change slides
function changeSlide(NR, n) {
    slideIndex += n;
    let slides = document.getElementsByClassName(`slide${NR}`);

    if (slideIndex < 1) {
        slideIndex = slides.length;
    } else if (slideIndex > slides.length) {
        slideIndex = 1;
    }

    showSlide(NR, slideIndex);
    document.dispatchEvent(new Event("slideChange"));
}

// Function to show a specific slide
function showSlide(slideGroup, e) {
    let slides = document.getElementsByClassName(`slide${slideGroup}`);
    if (e > slides.length) slideIndex = 1;
    else if (e < 1) slideIndex = slides.length;
    else slideIndex = e;

    for (let n = 0; n < slides.length; n++) {
        slides[n].style.display = "none";
        slides[n].classList.remove("active-slide", "previous-slide", "next-slide");
    }

    // If only one slide is present, set it as active-slide only
    if (slides.length === 1) {
        slides[0].style.display = "flex";
        slides[0].classList.add("active-slide");
    } else {
        if (slides[slideIndex - 1]) {
            slides[slideIndex - 1].style.display = "flex";
            slides[slideIndex - 1].classList.add("active-slide");
        }

        let prevIndex = slideIndex - 2 >= 0 ? slideIndex - 2 : slides.length - 1;
        if (slides[prevIndex]) {
            slides[prevIndex].style.display = "flex";
            slides[prevIndex].classList.add("previous-slide");
        }

        let nextIndex = slideIndex < slides.length ? slideIndex : 0;
        if (slides[nextIndex]) {
            slides[nextIndex].style.display = "flex";
            slides[nextIndex].classList.add("next-slide");
        }

        // Preload the next 2 slides
        preloadNextSlides(slideGroup, slideIndex);
    }

    storeLastSlide(slideGroup, slideIndex);
}

// Function to preload the next 2 slides after the current and next slide
function preloadNextSlides(slideGroup, currentSlideIndex) {
    const slides = document.getElementsByClassName(`slide${slideGroup}`);
    const nextSlides = [currentSlideIndex + 1, currentSlideIndex + 2, currentSlideIndex + 3]; // Next 3 slides

    nextSlides.forEach((index) => {
        if (slides[index]) {
            const img = slides[index].querySelector("img");
            if (img && img.loading !== "eager") {
                img.loading = "eager"; // Preload image
            }

            const video = slides[index].querySelector("video");
            if (video && video.preload !== "auto") {
                video.preload = "auto"; // Preload video
            }
        }
    });
}

// Lazy load and preload visible slides
document.addEventListener("DOMContentLoaded", function() {
    function preloadVisibleSlides() {
        document.querySelectorAll(".active-slide img.image-slide, .next-slide img.image-slide, .previous-slide img.image-slide")
            .forEach(img => img.loading = "eager");
    }

    function lazyLoadOthers() {
        document.querySelectorAll("img.image-slide").forEach(img => {
            if (!img.loading) img.loading = "lazy";
        });

        document.querySelectorAll("video.videofront").forEach(video => {
            if (video.preload !== "auto") video.preload = "none";
        });
    }

    preloadVisibleSlides();
    lazyLoadOthers();
    document.addEventListener("slideChange", preloadVisibleSlides);
});

// Function to get the highest lightbox number
function getHighestLightboxNumber() {
    const lightboxes = document.querySelectorAll('[id^="Lightbox_"]');
    let highest = 0;
    lightboxes.forEach(lightbox => {
        const id = lightbox.id;
        const number = parseInt(id.replace('Lightbox_', ''));
        if (number > highest) highest = number;
    });
    return highest;
}

// Function to set up pointer interaction
function setupPointer() {
    const Xmax = getHighestLightboxNumber();
    const pointerElement = document.getElementById("before-pointer");

    pointerElement.onclick = function() {
        openLightbox(Xmax);
        showSlide(Xmax, 1);
    };
}

window.onload = setupPointer;

// Function to close the lightbox
function closeLightbox(lightboxId) {
    document.getElementById(`Lightbox_${lightboxId}`).style.display = "none";
    pauseVideo(lightboxId);

    document.getElementById(`projecttitle_${lightboxId}`).style.display = "none";
    document.getElementById("mouseTarget").style.display = "flex";
    document.body.style.overflow = "";
    document.getElementById("rowid").style.display = "grid";
    document.querySelector("footer").style.display = "flex";
    document.getElementById("social_elements2").style.display = "";

    window.scrollTo({ top: lastScrollPosition, behavior: "smooth" });
    window.onkeydown = null;
    scale(x);
}

// Function to pause video when lightbox is closed
function pauseVideo(lightboxId) {
    document.querySelectorAll(`#Lightbox_${lightboxId} video`).forEach(video => {
        video.pause();
        video.currentTime = 0;
    });
}

// Function to set up key events for navigation
function setKeys(lightboxId) {
    window.onkeydown = function(e) {
        const key = e.key || e.code;

        if (key === "Escape") {
            closeLightbox(lightboxId);
        } else if (key === "ArrowRight") {
            changeSlide(lightboxId, 1);
        } else if (key === "ArrowLeft") {
            changeSlide(lightboxId, -1);
        }
    };
}